package com.gerenciadorrural.modules.farms.api;
import com.gerenciadorrural.modules.farms.application.GetCurrentFarmProfile; import com.gerenciadorrural.modules.farms.domain.FarmProfile; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/farms/current") public class FarmProfileController {private final GetCurrentFarmProfile useCase;public FarmProfileController(GetCurrentFarmProfile useCase){this.useCase=useCase;}@GetMapping public ResponseEntity<Response> current(@ResolvedTenantContext TenantContext context){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Response.from(useCase.execute(context)));}public record Response(String id,String organizationId,String name,String status){static Response from(FarmProfile f){return new Response(f.id().toString(),f.organizationId().toString(),f.name(),f.status());}}}
